                post_hook={
                    "sql": "CREATE or replace TABLE MAPLEMONK.shipment_status_mapping ( SHIPPING_STATUS string(16777216), Mapped_Status string(16777216) ); Insert INTO MAPLEMONK.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists MAPLEMONK.facility_pincode( facility string, pincode string ); CREATE OR REPLACE TABLE MAPLEMONK.marketplace_mapping ( marketplace STRING, final_marketplace STRING ); INSERT INTO MAPLEMONK.marketplace_mapping (marketplace, final_marketplace) VALUES (\'AJIO_OMNI\', \'AJIO\'), (\'MYNTRAPPMP_DEL\', \'MYNTRA\'), (\'MYNTRAPPMP_BHIWANDI\', \'MYNTRA\'), (\'AJIO_DEL\', \'AJIO\'), (\'MYNTRAPPMP_GGN\', \'MYNTRA\'), (\'NYKAA_FASHION_DEL\', \'NYKAA\'), (\'NYKAA_MAN_BHIWANDI_NEW\', \'NYKAA\'), (\'NYKAA_COM_DEL\', \'NYKAA\'), (\'NYKAA_MH_BHIWANDI\', \'NYKAA\'), (\'AJIO_GGN\', \'AJIO\'), (\'FLIPKART_BHIWANDI\', \'FLIPKART\'), (\'AMAZON.IN\', \'AMAZON\'), (\'WEBSITE\',\'WEBSITE\'), (\'AMAZON_FLEX_API_XIUQ__BHIWANDI\',\'AMAZON FLEX\'), (\'AMAZON_BHIWANDI\',\'AMAZON\'); create or replace table MAPLEMONK.FREAKINS_DB_sales_consolidated_intermediate as select b.customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(coalesce(b.source_name,b.FINAL_UTM_SOURCE)) AS SOURCE ,d.ORDER_ID ,d.reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,d.SUBORDER_QUANTITY quantity ,COALESCE((IFNULL(d.SELLING_PRICE, 0) - IFNULL(d.tax, 0) - IFNULL(d.SHIPPING_PRICE,0)),b.GROSS_SALES_BEFORE_TAX) AS GROSS_SALES_BEFORE_TAX ,COALESCE(d.DISCOUNT,b.DISCOUNT_BEFORE_TAX) AS DISCOUNT ,COALESCE(d.tax,b.TAX) TAX ,COALESCE(d.SHIPPING_PRICE,b.SHIPPING_PRICE) SHIPPING_PRICE ,COALESCE((d.SELLING_PRICE- d.SHIPPING_PRICE),b.TOTAL_SALES) AS SELLING_PRICE ,UPPER(d.order_status) as OMS_order_status ,UPPER(coalesce(b.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,d.awb) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(GATEWAY) > 0, GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(d.payment_mode) Payment_Mode ,Upper(coalesce(d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when d.return_flag=0 and lower(coalesce(d.order_status,b.order_status)) like any (\'%cancel%\') then cast(suborder_quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,b.SKU_CODE commonsku ,upper(d.warehouse_name) WAREHOUSE ,coalesce(b.pincode,d.pincode) as pincode ,fa.pincode as source_pincode ,b.discount_codes ,b.cancelled_at ,b.refund_date ,b.refund_value ,b.SKU_SIZE AS size ,b.SKU_GENDER AS Gender ,b.SKU_VERTICAL AS Vertical ,b.SKU_PRODUCT_ID AS S_Product_ID ,b.SKU_VARIANT_ID AS Variant_ID ,b.SKU_PRODUCT_TITLE AS Product_title ,b.SKU_STYLE_CODE AS Style_code ,b.SKU_VARIENT_SKU AS Varient_SKU ,b.SKU_PRODUCT_TYPE AS Product_type ,b.SKU_PRODUCT_STATUS AS Product_status ,b.SKU_PRODUCT_VENDOR AS Product_Vendoor ,null as invoiceDate ,CASE WHEN b.discount_codes LIKE \'%INF%\' THEN \'Influencer Sales\' WHEN b.discount_codes LIKE \'%AFF%\' THEN \'Affiliates Sales\' WHEN b.discount_codes LIKE \'%Emp%\' THEN \'Employee Code\' WHEN b.discount_codes LIKE \'%Gift%\' THEN \'Gift Coupon\' ELSE \'Other\' END AS discount_code_bucket from MAPLEMONK.FREAKINS_UNICOMMERCE_FACT_ITEMS d left join (select * from (select * ,row_number() over (partition by order_id,line_item_id order by order_timestamp desc) rw from MAPLEMONK.FREAKINS_DB_SHOPIFY_FACT_ITEMS) where rw=1 ) b on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from MAPLEMONK.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from MAPLEMONK.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) WHERE lower(d.marketplace) like any (\'%freakins%\') UNION ALL SELECT NULL AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.mapped_category)) AS PRODUCT_CATEGORY ,cast(null as string) AS PRODUCT_SUB_CATEGORY ,cast(ifnull(b.SKU,\'\') as string) commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,source_pincode ,cast(null as string) as discount_codes ,null as cancelled_at ,null as refund_date ,null as refund_value ,null as size ,null as Gender ,null as vertical ,null as E_Product_ID ,null as Variant_ID ,null as Product_title ,null as style_code ,null as Variant_SKU ,null as Product_type ,null as Product_status ,null as Product_vendor ,null as invoiceDate ,CAST(NULL AS STRING) AS discount_code_bucket FROM MAPLEMONK.FREAKINS_DB_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM MAPLEMONK.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN MAPLEMONK.category_mapping cm on upper(cm.category) = upper(b.mapped_category) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE \'%freakin%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\')) and reference_code not in (select distinct reference_code from MAPLEMONK.FREAKINS_unicommerce_fact_items) UNION ALL SELECT NULL AS customer_id ,UPPER(marketplace) AS shop_name ,UPPER(marketplace) AS marektplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.Product_Category)) AS PRODUCT_CATEGORY ,UPPER(b.product_sub_category) AS PRODUCT_SUB_CATEGORY ,sku_code commonsku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode ,CAST(NULL AS STRING) AS discount_codes ,null as cancelled_at ,null as refund_date ,null as refund_value ,b.sku_Size AS size ,b.sku_gender AS Gender ,b.sku_vertical AS vertical ,b.sku_Product_ID AS U_Product_ID ,b.sku_Variant_ID AS Variant_ID ,b.sku_Product_title AS Product_title ,b.sku_style_code AS style_code ,b.sku_Variant_SKU AS Variant_SKU ,b.sku_Product_type AS Product_type ,b.sku_Product_status AS Product_status ,b.sku_Product_vendor AS Product_vendor ,b.invoiceDate AS invoiceDate ,CAST(NULL AS STRING) AS discount_code_bucket FROM MAPLEMONK.FREAKINS_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from MAPLEMONK.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM MAPLEMONK.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN MAPLEMONK.category_mapping cm on upper(cm.category) = upper(b.product_category) WHERE NOT (LOWER(b.marketplace) LIKE ANY (\'%shopify%\') or LOWER(b.marketplace) LIKE ANY (\'%freakins%\') or LOWER(b.marketplace) LIKE ANY (\'%custom%\') or LOWER(b.marketplace) LIKE ANY (\'%b2b%\')) ; CREATE OR REPLACE TABLE MAPLEMONK.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM MAPLEMONK.FREAKINS_DB_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM MAPLEMONK.FREAKINS_DB_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE MAPLEMONK.FREAKINS_DB_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case when not(lower(coalesce(oms_order_status,order_status)) like \'%cancel%\') THEN \'GROSS SALE ORDERS\' when upper(coalesce(oms_order_status,order_status)) like \'%CANCEL%\' AND upper(coalesce(final_shipping_status,shipping_status)) like any (\'%DISPATCH%\',\'%TRANSIT%\') then \'CANCELLED DURING TRANSIT\' when upper(coalesce(oms_order_status,order_status)) like \'%CANCEL%\' AND upper(coalesce(final_shipping_status,shipping_status)) like any (\'%DELIVER%\') then \'CANCELLED DURING DELIVERY\' when upper(coalesce(oms_order_status,order_status)) like \'%CANCEL%\' AND upper(coalesce(final_shipping_status,shipping_status)) like any (\'%PICK%\',\'%PACK%\') then \'CANCELLED DURING PICKING-PACKING\' when upper(coalesce(oms_order_status,order_status)) like \'%CANCEL%\' AND upper(coalesce(final_shipping_status,shipping_status)) like any (\'%OPEN%\',\'%CONFIRM%\',\'CREATE\') then \'CANCELLED AFTER ORDER CREATION\' else \'CANCELLED\' end as Order_Type, sm.skucode as master_sku, upper(coalesce(sm.name,m.PRODUCT_NAME_FINAL)) as Product_Name_Main, upper(coalesce(sm.category,m.product_category)) as Product_Category_Main, upper(sm.colour) as Product_Colour, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM MAPLEMONK.FREAKINS_DB_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM MAPLEMONK.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM MAPLEMONK.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN MAPLEMONK.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace) LEFT JOIN ( select * from ( select *, row_number() over (partition by marketplace_sku order by 1) as rw from maplemonk.Freakins_WH_FINAL_SKU_MASTER where marketplace_sku <> \'\' ) where rw=1 ) sm ON lower(m.sku) = lower(sm.marketplace_sku) ; ALTER TABLE MAPLEMONK.FREAKINS_DB_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE MAPLEMONK.FREAKINS_DB_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM MAPLEMONK.FREAKINS_DB_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM MAPLEMONK.FREAKINS_DB_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM MAPLEMONK.FREAKINS_DB_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM MAPLEMONK.FREAKINS_DB_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE MAPLEMONK.FREAKINS_DB_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); create or replace table maplemonk.freakins_db_sales_consolidated as select final_marketplace, customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, Order_Type, master_sku, Product_Name_Main, Product_Category_Main, Product_Colour, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, size, Gender, Vertical, S_Product_ID, Variant_ID, Product_title, Style_code, Varient_SKU, Product_type, Product_status, Product_Vendoor, invoiceDate, discount_code_bucket, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, null as Original_Return_Value, null as Return_Reference_Code, \'Sale\' as Type, from maplemonk.freakins_db_sales_consolidated UNION ALL select final_marketplace, null customer_id_final, null acquisition_date, null first_complete_order_date, null Order_Quantity, \'GROSS SALE ORDERS\' Order_Type, null master_sku, null Product_Name_Main, null Product_Category_Main, null Product_Colour, s.maple_monk_id_phone, coalesce(s.customer_id,sh.customer_id) as customer_id, coalesce(s.SHOP_NAME,sh.shop_name) as Shop_name, coalesce(s.marketplace,sh.marketplace) as Marketplace, coalesce(s.CHANNEL,sh.FINAL_UTM_CHANNEL) as Channel, SOURCE, null ORDER_ID, null reference_code, null PHONE, null NAME, null EMAIL, null SHIPPING_LAST_UPDATE_DATE, null SKU, null PRODUCT_ID, null PRODUCT_NAME, null CURRENCY, coalesce(s.CITY,sh.city) City, coalesce(s.State,sh.state) State, null ORDER_STATUS, r.created_at Order_Date, null Order_Time, null QUANTITY, null GROSS_SALES_BEFORE_TAX, null DISCOUNT, null TAX, null SHIPPING_PRICE, null SELLING_PRICE, null OMS_order_status, null SHIPPING_STATUS, null FINAL_SHIPPING_STATUS, null SALEORDERITEMCODE, null SALES_ORDER_ITEM_ID, null AWB, null PAYMENT_GATEWAY, null Payment_Mode, null COURIER, null DISPATCH_DATE, null DELIVERED_DATE, null DELIVERED_STATUS, null RETURN_FLAG, null returned_quantity, null returned_sales, null cancelled_quantity, null Days_in_Shipment, null MARKETPLACE_ACQUISITION_DATE, null SKU_CODE, null PRODUCT_NAME_FINAL, null PRODUCT_CATEGORY, null PRODUCT_SUB_CATEGORY, null commonsku, null WAREHOUSE, null pincode, null source_pincode, null discount_codes, null size, null Gender, null Vertical, null S_Product_ID, null Variant_ID, null Product_title, null Style_code, null Varient_SKU, null Product_type, null Product_status, null Product_Vendoor, null invoiceDate, null discount_code_bucket, null new_customer_flag, null new_customer_flag_month, null acquisition_product, null acquisition_channel, null acquisition_marketplace, coalesce(r.item_refund_amount,s.selling_price) as Original_Return_Value, r.order_name as Return_Reference_Code, \'Return\' as Type, from maplemonk.freakins_returns_data r left join maplemonk.freakins_db_Sales_consolidated s on s.reference_code = r.order_name and s.saleorderitemcode = r.line_item_id left join maplemonk.freakins_db_shopify_fact_items sh on sh.order_name = r.order_name and sh.line_item_id = r.line_item_id where lower(return_type) like \'%refund%\' ; CREATE OR REPLACE TABLE MAPLEMONK.FREAKINS_DB_returns_consolidated AS SELECT UPPER(r.MARKETPLACE) AS Marketplace, cast(created_at as datetime) return_Date, UPPER(s.CHANNEL) AS Marketing_channel, SUM(ifnull(r.quantity,0)) AS TOTAL_RETURNED_QUANTITY, SUM(ifnull(item_refund_amount,0)) AS TOTAL_RETURN_AMOUNT, SUM(ifnull(s.TAX,0)) AS TOTAL_RETURN_TAX, SUM(ifnull(item_refund_amount,0)) - SUM(ifnull(s.TAX,0)) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM maplemonk.freakins_returns_data r LEFT JOIN maplemonk.freakins_db_Sales_consolidated s ON s.reference_code = r.order_name and s.saleorderitemcode = r.line_item_id WHERE lower(return_type) like \'%refund%\' GROUP BY r.Marketplace,RETURN_DATE,channel ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

